tar -xzf "$TMPD/o.tgz" -C "$NEW_REL_DIR" --no-same-owner || abort "extract failed" EXTRACT
OWNER=$(stat -c '%U:%G' "$CURRENT_ROOT/index.html")
chown "$OWNER" "$NEW_REL_DIR/index.html"
